<template>
  <section class="flex flex-col gap-10">
    <PageTitle title="Import Petitions" />
    <Card class="max-w-md w-full mx-auto">
      <CardContent>
        <div class="flex flex-col gap-4" :class="{ '!block': isCanvasserOrSubCanvasser }">
          <!--? MB in cases like this, we'll need autocompletes (component), cause of amount of projects-->
          <FilterByProject
            :value="params.project_id ? [params.project_id] : null"
            property-name="project_id"
            :statuses="['active']"
            :null-is-all="true"
            placeholder="Select Project"
            input-placeholder="Search project..."
            empty-text="No projects found"
            items-plural-name="projects"
            :is-multiple="false"
            :is-first-page-only="false"
            label="Project"
            :icon="BriefcaseBusinessIcon"
            @change="onProjectChange"
          />
          <template v-if="isAdminOrManager && params.project_id">
            <FilterByUser
              :value="params.canvasser_id ? [params.canvasser_id] : null"
              property-name="canvasser_id"
              :roles="['canvasser', 'subcontractor_canvasser']"
              :statuses="['active']"
              :project-ids="params.project_id ? [params.project_id] : undefined"
              :null-is-all="true"
              placeholder="Select Canvasser"
              input-placeholder="Search canvasser..."
              empty-text="No canvassers found"
              items-plural-name="canvassers"
              :is-multiple="false"
              :is-first-page-only="false"
              label="Canvasser"
              :icon="UserIcon"
            />
            <div class="flex flex-row">
              <Switch id="upload-on-canvassers-behalf" v-model="isUploadOnCanvassersBehalf" class="mr-4" />
              <label for="upload-on-canvassers-behalf">{{ importOnBehalfAlert.title }}</label>
            </div>
            <Alert v-if="isUploadOnCanvassersBehalf">
              <InfoIcon />
              <AlertDescription>
                {{ importOnBehalfAlert.note }}<br />
                {{ importOnBehalfAlert.caution }}
              </AlertDescription>
            </Alert>
          </template>
        </div>
      </CardContent>
      <CardFooter class="justify-end">
        <Button v-if="isImportButtonDisabled" class="h-10 px-4" variant="default" disabled> Import </Button>
        <NuxtLink
          v-else
          :to="{
            name: 'verification-ballots-import',
            query: {
              ...(isAdminOrManager && {
                canvasser_id: params.canvasser_id,
                is_upload_on_canvassers_behalf: isUploadOnCanvassersBehalf ? 'true' : 'false',
              }),
              project_id: params.project_id,
            },
          }"
        >
          <Button class="h-10 px-4" variant="default"> Import </Button>
        </NuxtLink>
      </CardFooter>
    </Card>
  </section>
</template>

<script setup lang="ts">
import { BriefcaseBusinessIcon, InfoIcon, UserIcon } from 'lucide-vue-next';
import { importOnBehalfAlert } from '~/constants/verifications/importOnBehalfAlert';

definePageMeta({
  roles: ['canvasser', 'subcontractor_canvasser', 'manager'],
  backLabel: 'selection',
});

const route = useRoute();

const isUploadOnCanvassersBehalf = ref(false);

const { isCanvasserOrSubCanvasser, userData, isAdminOrManager } = useUserRole();

const params = computed(() => ({
  project_id: (route.query.project_id?.toString() as string | null) || null,
  canvasser_id: isCanvasserOrSubCanvasser.value
    ? userData.value?.id || null
    : route.query.canvasser_id?.toString() || null,
}));

const isImportButtonDisabled = computed(() => {
  return !(params.value.project_id && (params.value.canvasser_id || isCanvasserOrSubCanvasser.value));
});

function onProjectChange() {
  navigateTo(
    {
      query: {
        ...route.query,
        canvasser_id: undefined,
      },
    },
    { replace: true }
  );
}

onMounted(() => {
  isUploadOnCanvassersBehalf.value = route.query.is_upload_on_canvassers_behalf === 'true';
});
</script>
